const body = $input.first().json.body || $input.first().json;
const p = body.data || body; const d = p.delivery;
const base = "http://localhost:3001/api";
if (!Number.isSafeInteger(p.interviewId) || p.interviewId < 1 || !d || !/^[a-f0-9]{64}$/.test(d.token || '') || !/^[a-f0-9-]{36}$/.test(d.requestId || '')) throw new Error('Authenticated TV2 delivery metadata required');
if (d.callbackUrl !== base + '/applications/interviews/' + p.interviewId + '/delivery') throw new Error('Callback destination must match configured API');
return [{json:{interviewId:p.interviewId, delivery:d}}];

const r = $input.first().json.data || $input.first().json;
const d = $('Validate delivery envelope').first().json.delivery; const p = r.payload;
if (r.claimed !== true || !p || p.interviewId !== $('Validate delivery envelope').first().json.interviewId || r.eventId !== d.eventId) throw new Error('Interview claim mismatch');
for (const key of ['candidateEmail','fromEmail','interviewerEmail']) if (!/^[^\s@]+@[^\s@]+[.][^\s@]+$/.test(p[key] || '')) throw new Error('Configured recipient and sender required');
if (!Number.isFinite(Date.parse(p.scheduledAt)) || !Number.isSafeInteger(p.applicationId) || !Number.isSafeInteger(p.round)) throw new Error('Invalid persisted schedule');
return [{json:{...p, delivery:d}}];

const e = $input.first().json; const p = $('Load interview payload').first().json;
const meet = e.hangoutLink || e.conferenceData?.entryPoints?.find(x => x.entryPointType === 'video')?.uri;
if (e.id !== p.delivery.eventId || e.status !== 'confirmed' || Date.parse(e.start?.dateTime) !== Date.parse(p.scheduledAt) || Date.parse(e.end?.dateTime) !== Date.parse(p.scheduledAt)+45*60000 || !/^https:\/\/meet[.]google[.]com\/[a-z]{3}-[a-z]{4}-[a-z]{3}$/.test(meet || '') || e.conferenceData?.createRequest?.status?.statusCode !== 'success') throw new Error('Calendar/Meet readback not confirmed');
return [{json:{...e,hangoutLink:meet, callback:{requestId:p.delivery.requestId,applicationId:p.applicationId,event:'CALENDAR_CONFIRMED',eventId:e.id,meetingLink:meet,scheduledAt:e.start.dateTime}}}];

const calendarItem = $('Verify Calendar readback').first().json;
const payload = $('Load interview payload').first().json;
const escapeHtml = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const candidateName = escapeHtml(payload.candidateName);
const candidateEmail = payload.candidateEmail;
const interviewerName = escapeHtml(payload.interviewerName);
const interviewerEmail = payload.interviewerEmail || '';
const round = payload.round || 1;
const fromEmail = payload.fromEmail;

const scheduledDate = new Date(payload.scheduledAt || Date.now());
const formattedTime = scheduledDate.toLocaleString('vi-VN', {
  timeZone: 'Asia/Ho_Chi_Minh',
  hour: '2-digit',
  minute: '2-digit',
  day: '2-digit',
  month: '2-digit',
  year: 'numeric',
  weekday: 'long'
});

// Link Google Meet thật do Google Calendar API sinh ra
const googleMeetUrl = calendarItem.hangoutLink;

const htmlTemplate = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <style>
    body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; background-color: #f4f6f9; margin: 0; padding: 20px; }
    .container { max-width: 620px; margin: 0 auto; background: #ffffff; border-radius: 12px; overflow: hidden; box-shadow: 0 4px 15px rgba(0,0,0,0.08); }
    .header { background: linear-gradient(135deg, #1e3a8a 0%, #3b82f6 100%); color: #ffffff; padding: 30px; text-align: center; }
    .header h1 { margin: 0; font-size: 22px; font-weight: 600; }
    .content { padding: 30px; color: #334155; line-height: 1.6; }
    .info-card { background: #f8fafc; border-left: 4px solid #3b82f6; padding: 20px; margin: 20px 0; border-radius: 0 8px 8px 0; }
    .info-item { margin: 8px 0; font-size: 15px; }
    .btn { display: inline-block; background: #2563eb; color: #ffffff !important; padding: 14px 28px; text-decoration: none; border-radius: 8px; font-weight: 600; text-align: center; margin: 15px 0; }
    .tips { background: #fefce8; border: 1px solid #fef08a; padding: 15px; border-radius: 8px; font-size: 14px; color: #713f12; margin-top: 20px; }
    .footer { text-align: center; font-size: 13px; color: #94a3b8; padding: 20px; border-top: 1px solid #e2e8f0; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>THƯ MỜI PHỎNG VẤN TRỰC TUYẾN</h1>
      <p style="margin: 5px 0 0 0; opacity: 0.9;">Enterprise HR & Talent Ecosystem</p>
    </div>
    <div class="content">
      <p>Kính gửi <strong>${candidateName}</strong>,</p>
      <p>Cảm ơn bạn đã quan tâm và ứng tuyển vào đội ngũ công nghệ của chúng tôi. Hội đồng tuyển dụng trân trọng kính mời bạn tham dự buổi phỏng vấn Vòng ${round} với thông tin chi tiết dưới đây:</p>

      <div class="info-card">
        <div class="info-item">⏰ <strong>Thời gian:</strong> ${formattedTime}</div>
        <div class="info-item">🎯 <strong>Vòng phỏng vấn:</strong> Vòng ${round} (Chuyên môn Kỹ thuật)</div>
        <div class="info-item">👤 <strong>Người phỏng vấn:</strong> ${interviewerName} ${interviewerEmail ? '(' + interviewerEmail + ')' : ''}</div>
        <div class="info-item">💻 <strong>Hình thức:</strong> Trực tuyến qua Google Meet</div>
      </div>

      <div style="text-align: center;">
        <a href="${googleMeetUrl}" class="btn" target="_blank">👉 Tham Gia Google Meet Ngay</a>
      </div>

      <div class="tips">
        💡 <strong>Lưu ý chuẩn bị:</strong>
        <ul style="margin: 5px 0 0 0; padding-left: 20px;">
          <li>Vui lòng kiểm tra camera và microphone trước giờ phỏng vấn 10 phút.</li>
          <li>Chuẩn bị sẵn không gian yên tĩnh và các tài liệu/dự án tiêu biểu đã thực hiện.</li>
        </ul>
      </div>

      <p style="margin-top: 25px;">Chúc bạn có một buổi phỏng vấn thành công tốt đẹp!</p>
      <p>Trân trọng,<br><strong>Phòng Thu Hút Nhân Tài (Talent Acquisition Team)</strong></p>
    </div>
    <div class="footer">
      © 2026 Enterprise Corporation. Lịch phỏng vấn được tạo tự động bởi n8n & Google Calendar.
    </div>
  </div>
</body>
</html>
`;

return {
  json: {
    fromEmail: fromEmail,
    candidateName: candidateName,
    candidateEmail: candidateEmail,
    interviewerName: interviewerName,
    interviewerEmail: interviewerEmail,
    round: round,
    formattedTime: formattedTime,
    googleMeetUrl: googleMeetUrl,
    telegramChatId: payload.telegramChatId || payload.chatId,
    emailSubject: `[Enterprise Corp] Thư mời phỏng vấn Vòng ${round} - Ứng viên ${candidateName}`,
    emailHtml: htmlTemplate,
    telegramAlert: `📅 <b>LỊCH PHỎNG VẤN MỚI</b>\n• Ứng viên: <b>${candidateName}</b>\n• Vòng: <b>Vòng ${round}</b>\n• Người PV: <b>${interviewerName}</b>\n• Thời gian: <code>${formattedTime}</code>\n• Google Meet: <a href="${googleMeetUrl}">${googleMeetUrl}</a>`
  }
};

const m = $input.first().json; const p = $('Load interview payload').first().json;
if (!m.messageId || !Array.isArray(m.accepted) || m.accepted.length !== 1 || String(m.accepted[0]).toLowerCase() !== p.candidateEmail.toLowerCase() || (m.rejected || []).length) throw new Error('SMTP acceptance not confirmed');
return [{json:{requestId:p.delivery.requestId,applicationId:p.applicationId,event:'SMTP_ACCEPTED',eventId:p.delivery.eventId,recipient:p.candidateEmail,messageId:m.messageId}}];
